  "Elfelejtetted? Kapcsold ki a szinkront azon a készüléken, ahol működik, majd kapcsold be újra, és válassz új jelmondatot.": "Забыл? Выключи синхронизацию на устройстве, где она работает, включи снова и выбери новую парольную фразу.",
