  "A saját imalista szinkronját egy másik készülékeden kikapcsoltad. Az imalistád ezen a készüléken megmaradt.": "Ты выключил синхронизацию своего молитвенного списка на другом устройстве. Твой молитвенный список на этом устройстве сохранён.",
  "Kikapcsolod a szinkront? A szerveren tárolt titkosított Biblia-adataidat töröljük. Ezen és a többi készülékeden minden megmarad, de ott is leáll a szinkron.": "Выключить синхронизацию? Мы удалим твои зашифрованные данные Библии на сервере. На этом и других твоих устройствах всё останется, но синхронизация там тоже остановится.",
  "Kikapcsolod a saját imalista szinkronját? A szerveren tárolt titkosított imalistádat töröljük. A telefonjaidon megmarad.": "Выключить синхронизацию своего молитвенного списка? Мы удалим твой зашифрованный молитвенный список на сервере. На твоих телефонах он останется.",
  "A kikapcsolás most nem sikerült, mert a szervert nem értük el. Próbáld újra később.": "Выключить сейчас не удалось: сервер недоступен. Попробуй позже.",
