  "A másik telefonon nyisd meg az .apk fájlt a Fájlok alkalmazásban, és koppints a Telepítés gombra. Ha a telefon kéri, egyszer engedélyezd az „Ismeretlen alkalmazások telepítése” beállítást annak az alkalmazásnak, amellyel a fájlt megnyitottad.": "На другом телефоне откройте файл .apk в приложении «Файлы» и нажмите «Установить». Если телефон попросит, один раз разрешите «Установку неизвестных приложений» для приложения, которым вы открыли файл.",
