  // ===== 2026-11-02 Gerah escrow + weekly goal (owner TG 33434/33435, decision A TG 1322, card 8ed3c59e; the daily item is the signed wording) =====
  "Napi Bibliaolvasás, heti céllal. Minden nap, amikor eléred a napra beállított olvasási célodat, Gerah kerül letétbe a cél hossza szerint: legalább 10 perces cél után 1, legalább 20 perces után 2, legalább 30 perces után 3; az 5 perces cél után nem jár. Naponta legfeljebb 3 gerah. A letét akkor kerül a tárcádba, ha 7 egymást követő napon eléred a napi célodat. Ha egy nap kimarad, a letét elvész, és a hét nap elölről indul. A Gerah-t a PrepperPapa alkalmazás tárcája tárolja: a Wordlightban végzett olvasásért akkor jár, ha nálad telepítve van a PrepperPapa alkalmazás. A reggeli ébresztős felolvasás is beleszámít.": "Ежедневное чтение Библии с недельной целью. В каждый день, когда ты достигаешь цели чтения, установленной на этот день, Gerah помещается на депозит по длине цели: 1 за цель не менее 10 минут, 2 за не менее 20 минут, 3 за не менее 30 минут; цель в 5 минут ничего не даёт. Не более 3 gerah в день. Депозит переходит в твой кошелёк, когда ты достигаешь дневной цели 7 дней подряд. Если ты пропускаешь день, депозит сгорает, и 7 дней начинаются заново. Gerah хранится в кошельке приложения PrepperPapa: за чтение в Wordlight ты получаешь её только если на твоём устройстве установлено приложение PrepperPapa. Чтение утреннего будильника тоже засчитывается.",
  "Napi Bibliaolvasás, heti céllal: minden nap, amikor eléred a napra beállított olvasási célodat (legalább {p} perc), 1 gerah kerül letétbe. A letét akkor kerül a tárcádba, ha {h} egymást követő napon eléred a napi célodat; ha egy nap kimarad, a letét elvész, és a {h} nap elölről indul. A reggeli ébresztős felolvasás is beleszámít.": "Ежедневное чтение Библии с недельной целью: в каждый день, когда ты достигаешь цели чтения, установленной на этот день (не менее {p} минут), 1 gerah помещается на депозит. Депозит переходит в твой кошелёк, когда ты достигаешь дневной цели {h} дней подряд; если ты пропускаешь день, депозит сгорает, и {h} дней начинаются заново. Чтение утреннего будильника тоже засчитывается.",
  "Ma {n} gerah-t letétbe helyeztünk. Heti cél: {k} / {h} nap.": "Сегодня {n} gerah помещено на депозит. Недельная цель: {k} / {h} дней.",
  "Heti cél teljesítve: {n} gerah a tárcádba került!": "Недельная цель достигнута: {n} gerah перешло в твой кошелёк!",
