Object.assign(window.PP_FORD_SZOTAR.ru, {
  "A Gerah a közösségen belüli elszámolás egysége, nem pénz és nem fizetőeszköz. A PrepperPapa nem váltja át pénzre, nem garantálja az értékét, és nem részese a tagok közötti ügyleteknek. A tagok közötti vitákat és elszámolást a felhasználók egymás közt rendezik. Az offline fizetésnél előfordulhat, hogy ugyanazt a Gerah-t kétszer költik el; ennek kockázata a felhasználókat terheli.": "Gerah — единица взаимных расчётов внутри сообщества, не деньги и не платёжное средство. PrepperPapa не обменивает её на деньги, не гарантирует её стоимость и не является стороной сделок между участниками. Споры и расчёты между участниками пользователи решают между собой. При офлайн-платежах одна и та же Gerah может быть потрачена дважды; этот риск несут пользователи."
});
