// 2026-11-03: the guided prayer's encouragements (Énok, IMA_VEZ_BUZD; owner TG 34198) and the Charon voice's
// visible name (owner TG 34202-34212: Mihály, in each language its own form)
Object.assign(window.PP_FORD_SZOTAR.ru, {
  "A csend nem üresség, hanem jelenlét. Nem neked kell rendbe tenned a hetet, mielőtt Isten elé állsz: elég, ha megállsz. Ő a zaj fölött is Isten, és ma a te szívedben is az akar lenni.": "Тишина не пустота, а присутствие. Тебе не нужно приводить в порядок свою неделю, прежде чем предстать перед Богом: достаточно остановиться. Он Бог и над всяким шумом, и сегодня Он хочет быть Богом и в твоём сердце.",
  "Az aggodalom mindig a holnapban él, a hála a mában. Amikor megköszönöd, amit már kaptál, a félelemnek kevesebb helye marad. Ma ne a terhet sorold elő először, hanem azt, amit Isten már megtett.": "Тревога всегда живёт в завтрашнем дне, благодарность в сегодняшнем. Когда ты благодаришь за то, что уже получил, страху остаётся меньше места. Сегодня перечисли сначала не свои тяготы, а то, что Бог уже сделал.",
  "Isten nem félig bocsát meg. Ha megvallottad, nem kell újra elővenned és újra hordoznod. Ma tiszta lappal indulsz, nem azért, mert jó voltál, hanem mert ő hű és igaz.": "Бог не прощает наполовину. Если ты исповедал это, тебе не нужно снова доставать это и снова нести. Сегодня ты начинаешь с чистого листа, не потому что был хорошим, а потому что Он верен и праведен.",
  "Ami először jön, az szabja meg a többit. Ha ma az ő országa kerül az első helyre, a teendőid nem tűnnek el, de a helyükre kerülnek. Bízd rá a sorrendet, és figyeld meg, mi adatik hozzá.": "То, что стоит первым, определяет всё остальное. Если сегодня Его Царство займёт первое место, твои дела не исчезнут, но встанут на своё место. Доверь Ему порядок и посмотри, что приложится тебе.",
  "Nem kell kopogtatva, lehajtott fejjel jönnöd. A kegyelem trónja elé bizalommal járulhatsz, mert Jézus már kitárta az ajtót. Amire ma szükséged van, azt kérd bátran: ez a megfelelő idő.": "Тебе не нужно робко стучаться, опустив голову. Ты можешь с дерзновением приступить к престолу благодати, потому что Иисус уже широко открыл дверь. О том, что тебе нужно сегодня, проси смело: сейчас благовременно.",
  "A hála nem a körülményekből fakad, hanem abból, aki a körülmények fölött áll. Nem mindenért, de mindenben adhatsz hálát. Ma keresd meg azt az egy pontot a nehézségben, ahol Isten keze már látszik.": "Благодарность рождается не из обстоятельств, а из Того, Кто стоит над ними. Не за всё, но во всём ты можешь благодарить. Сегодня найди в трудности ту одну точку, где рука Божья уже видна.",
  "Jézus nem azt mondja, hogy előbb erősödj meg, és utána jöhetsz. A fáradtakat hívja. Tedd le nála, ami nyom, ne magyarázd, csak tedd le. A nyugalom nála kezdődik, nem a feladatok végén.": "Иисус не говорит: сначала окрепни, а потом приходи. Он зовёт утружденных. Положи перед Ним то, что тебя давит, не объясняй, просто положи. Покой начинается у Него, а не в конце твоих дел.",
  "Ha az Úr a pásztorod, nem egyedül kell kitalálnod az utat. Ő tudja, hol a legelő és hol a csendes víz. Ma ne a hiányt számold, hanem kövesd a hangját, és meglátod, hogy nem szűkölködsz.": "Если Господь твой пастырь, тебе не нужно одному искать путь. Он знает, где пажить и где тихие воды. Сегодня не считай того, чего не хватает, а следуй за Его голосом, и увидишь, что ни в чём не будешь нуждаться.",
  "A gyengeséged nem akadály Isten előtt, hanem tér, ahol az ő ereje megmutatkozik. Ma ne szégyelld, ahol kevés vagy. Pont ott mondja neked: elég az én kegyelmem.": "Твоя слабость не преграда перед Богом, а пространство, где являет себя Его сила. Сегодня не стыдись того, в чём ты мал. Именно там Он говорит тебе: довольно для тебя благодати Моей.",
  "A félelem azt súgja, hogy egyedül vagy. Isten azt mondja: veled vagyok. Nem a félelem nagysága dönt, hanem az, hogy kinek a jobbja tart. Ma kapaszkodj abba a kézbe, ami nem enged el.": "Страх шепчет, что ты один. Бог говорит: Я с тобой. Решает не величина страха, а то, чья десница тебя держит. Сегодня держись за руку, которая тебя не отпустит.",
  "Nem kell mindent értened ahhoz, hogy jó úton járj. Elég, ha minden lépésnél őt ismered el. A térkép nála van, neked a következő lépés jut. Tedd meg ma bizalommal.": "Не нужно понимать всё, чтобы идти верным путём. Достаточно на каждом шаге познавать Его. Карта у Него, а тебе дан следующий шаг. Сделай его сегодня с доверием.",
  "Valaki ma nehezebb terhet visz, mint te. Lehet, hogy egy telefon, egy jó szó vagy egy ima az, ami könnyít rajta. Krisztus törvénye ilyen egyszerű lépésekben töltődik be. Kérdezd meg Istent: kinek kellek ma?": "Кто-то сегодня несёт ношу тяжелее твоей. Может быть, звонок, доброе слово или молитва облегчат её. Закон Христов исполняется в таких простых шагах. Спроси Бога: кому я нужен сегодня?",
  "A megbocsátás nem azt jelenti, hogy nem fájt. Azt jelenti, hogy nem te viszed tovább a számlát. Ahogy Isten Krisztusban elengedte a tiédet, úgy engedheted el te is. Ma szabadabban léphetsz ki ebből az imából.": "Прощение не означает, что не было больно. Оно означает, что ты больше не несёшь этот счёт дальше. Как Бог во Христе простил тебе, так и ты можешь отпустить. Сегодня ты можешь выйти из этой молитвы свободнее.",
  "A kifáradás nem bukás. Aki az Úrban bízik, annak az ereje nem egyszer adatik, hanem újra és újra megújul. Ma nem kell repülnöd, ha csak járni tudsz. Ő ott is megtart, és nem fáradsz el.": "Усталость не поражение. Надеющимся на Господа сила даётся не однажды, она обновляется снова и снова. Сегодня тебе не нужно летать, если ты можешь только идти. Он поддержит тебя и там, и ты не утомишься.",
  "Ha az Úr a világosságod, a sötétség nem dönthet helyetted. Kitől féljek? Ez nem dac, hanem bizalom. Ma nézz szembe azzal, ami nyugtalanít, és mondd ki hangosan: az Úr az én életem erőssége.": "Если Господь твой свет, тьма не может решать за тебя. Кого мне бояться? Это не вызов, а доверие. Сегодня посмотри в лицо тому, что тебя тревожит, и скажи вслух: Господь крепость жизни моей.",
  "A Lélek gyümölcse nem erőfeszítésből terem, hanem abból, hogy közel maradsz hozzá. Nem neked kell előállítanod a békességet és a türelmet. Maradj ma a szőlőtőn, és a gyümölcs megjön.": "Плод Духа растёт не из усилий, а из того, что ты остаёшься рядом с Ним. Не тебе нужно производить мир и терпение. Пребывай сегодня в лозе, и плод придёт.",
  "A legtöbb sebet nem a tett, hanem a gyors szó ejti. Ma figyelj egy kicsit tovább, mielőtt válaszolsz. Lehet, hogy a csendben meghallod, mit akar mondani a másik, és mit akar mondani Isten.": "Большинство ран наносит не поступок, а поспешное слово. Сегодня послушай чуть дольше, прежде чем ответить. Может быть, в тишине ты услышишь, что хочет сказать другой, и что хочет сказать Бог.",
  "A madarak nem aggódnak a holnapi kenyér miatt, mégis van mit enniük. Te sokkal értékesebb vagy előtte. Ma, amikor a gond megszólal, nézz fel egy pillanatra, és emlékezz: az Atya tud rólad.": "Птицы не заботятся о завтрашнем хлебе, и всё же им есть что есть. Ты для Него гораздо ценнее их. Сегодня, когда заговорит забота, на мгновение подними глаза и вспомни: Отец знает о тебе.",
  "A vezetőkért mondott ima nem politika, hanem szolgálat. Akár egyetértesz velük, akár nem, Isten kezében vannak. Imádkozz értük ma, hogy csendes és nyugodalmas életet élhessünk, te és a családod is.": "Молитва за начальствующих не политика, а служение. Согласен ты с ними или нет, они в руке Божьей. Помолись сегодня за них, чтобы нам проводить тихую и безмятежную жизнь, и тебе, и твоей семье.",
  "A reménység nem azon múlik, mit látsz, hanem azon, kiben hiszel. Isten nem kis adagban adja, hanem bővölködni akar benned. Ma engedd, hogy a Szentlélek töltse be azt, ami kiürült.": "Надежда зависит не от того, что ты видишь, а от того, в Кого ты веришь. Бог даёт её не малыми порциями, а хочет, чтобы ты обогатился ею. Сегодня позволь Святому Духу наполнить то, что опустело.",
  "Bátorság Istentől kérni, hogy vizsgáljon meg. Nem azért teszi, hogy elítéljen, hanem hogy vezessen. Ami ma előkerül, azt ne rejtsd el, add oda neki. Ő az örökkévalóság útjára akar vinni.": "Нужна смелость, чтобы просить Бога испытать тебя. Он делает это не чтобы осудить, а чтобы вести. То, что сегодня выйдет на свет, не прячь, отдай Ему. Он хочет направить тебя на путь вечный.",
  "A hálaadás a kapu, amin bejutsz az ő jelenlétébe. Nem kell nagy szavakat keresned. Kezdd azzal, ami ma eszedbe jut, és figyeld meg, hogyan nyílik meg a szíved a dicséretre.": "Благодарение это врата, через которые ты входишь в Его присутствие. Не нужно искать громких слов. Начни с того, что сегодня приходит на ум, и посмотри, как твоё сердце открывается для хвалы.",
  "Nincs olyan munka, ami túl kicsi ahhoz, hogy az Úrnak végezd. A mai feladataid, a rutin is, istentisztelet lehet. Tedd ma lélekből, mintha neki tennéd, mert valójában neki teszed.": "Нет работы слишком малой, чтобы делать её для Господа. Твои сегодняшние дела, даже рутина, могут быть служением Богу. Делай их сегодня от души, как для Него, потому что на самом деле ты делаешь их для Него.",
  "A világ békessége a körülményektől függ, Jézusé nem. Ő úgy adja, hogy a vihar közepén is megmarad. Ma, ha a szíved nyugtalan, ne a vihar elcsendesedésére várj, hanem vedd át tőle a békességét.": "Мир этого мира зависит от обстоятельств, мир Иисуса нет. Он даёт его так, что он остаётся и посреди бури. Сегодня, если твоё сердце смущено, не жди, пока утихнет буря, а прими от Него Его мир.",
  "Az ige nem reflektor, ami az egész utat bevilágítja, hanem lámpás a lábad elé. Elég a következő lépéshez. Ma ne a távoli kanyarokon aggódj, hanem tedd meg azt a lépést, amit most látsz.": "Слово не прожектор, освещающий весь путь, а светильник ноге твоей. Его хватает на следующий шаг. Сегодня не тревожься о дальних поворотах, а сделай тот шаг, который видишь сейчас.",
  "Az erő nem a te izmodból jön, hanem az ő hatalmából. Isten fegyverzete készen áll, csak fel kell öltened. Ma reggel tudatosan vedd magadra: az igazság, a hit, az ige ott van melletted.": "Сила приходит не из твоих мышц, а из Его могущества. Всеоружие Божье готово, нужно только облечься в него. Сегодня утром облекись в него сознательно: истина, вера и Слово рядом с тобой.",
  "Bármi történt tegnap, ma reggel Isten irgalma újra friss. Nem fogyott el, nem kopott meg. Ez a nap új kezdet, mert nagy az ő hűsége, és nem a tiéd tartja meg a napot.": "Что бы ни случилось вчера, этим утром милосердие Божье снова свежее. Оно не иссякло, не истёрлось. Этот день новое начало, потому что велика верность Его, и не твоя верность держит этот день.",
  "Amit Isten elkezdett benned, azt nem hagyja félbe. Lehet, hogy most nem látod a végét, de ő látja. Ma nyugodj meg abban, hogy a munka az ő kezében van, és ő elvégzi.": "То, что Бог начал в тебе, Он не оставит незавершённым. Может быть, сейчас ты не видишь конца, но Он видит. Сегодня успокойся в том, что дело в Его руках, и Он совершит его.",
  "Mihály": "Михаил",
});

// fiok-mentes: account backup and restore (owner TG 34415, 2026-11-03)
Object.assign(window.PP_FORD_SZOTAR.ru, {
  "Mentés a fiókodba": "Резервная копия в аккаунте",
  "Ha bekapcsolod, a teljes mentésedet (a készüléken tárolt adataidat, például jegyzeteket, kijelöléseket, könyvjelzőket, olvasási terveket és beállításokat) a fiókodba töltheted, egy általad választott mentési kulccsal titkosítva, és új telefonon ugyanazzal a fiókkal és kulccsal visszatöltheted.": "Если включить, можно загрузить в аккаунт полную резервную копию (данные, хранящиеся на этом устройстве, например заметки, выделения, закладки, планы чтения и настройки), зашифрованную выбранным вами ключом копии, и восстановить её на новом телефоне с тем же аккаунтом и ключом.",
  "Mentés a fiókba most": "Сохранить в аккаунт сейчас",
  "Visszatöltés a fiókból": "Восстановить из аккаунта",
  "Automatikus mentés naponta": "Автоматическая ежедневная копия",
  "Naponta legfeljebb egyszer, csak ha változott valami. Ehhez a mentési kulcsból képzett kulcs ezen a készüléken marad, amíg be van kapcsolva; magát a mentési kulcsot nem tároljuk.": "Не чаще раза в день и только если что-то изменилось. Для этого ключ, полученный из ключа копии, остаётся на этом устройстве, пока функция включена; сам ключ копии не хранится.",
  "A fiókba mentéshez be kell jelentkezned.": "Чтобы сохранить копию в аккаунт, нужно войти.",
  "A fiókba mentés most nem érhető el, később próbáld újra.": "Сохранение в аккаунт сейчас недоступно, попробуйте позже.",
  "A mentés túl nagy a fiókhoz ({m} MB, legfeljebb {max} MB). Készíts helyi teljes mentést fájlba.": "Копия слишком большая для аккаунта ({m} МБ, не более {max} МБ). Сделайте вместо этого локальную полную копию в файл.",
  "A fiókodban tárolt mentés: {t} ({m} MB).": "Копия в аккаунте: {t} ({m} МБ).",
  "A fiókodban még nincs mentés ebből az alkalmazásból.": "В вашем аккаунте ещё нет копии из этого приложения.",
  "Az automatikus mentés az első kézi mentés után indul.": "Автоматическое копирование начнётся после первой ручной копии.",
  "A fiókodban már van egy mentés ({t}). Lecseréled erre? Az eddigi biztonsági példányként megmarad.": "В аккаунте уже есть копия ({t}). Заменить её этой? Текущая сохранится как страховочная копия.",
  "Mentés megszakítva, nem töltöttünk fel semmit.": "Копирование отменено, ничего не загружено.",
  "Feltöltés a fiókodba…": "Загрузка в аккаунт…",
  "Mentés feltöltve a fiókodba.": "Копия загружена в ваш аккаунт.",
  "A fiókodban két mentés van: a legutóbbi ({a}) és az előző ({b}). Melyiket töltsük vissza?": "В аккаунте две копии: последняя ({a}) и предыдущая ({b}). Какую восстановить?",
  "A legutóbbit": "Последнюю",
  "Az előzőt": "Предыдущую",
  "A visszatöltés a készüléken levő adataidat felülírja a fiókban tárolt mentéssel ({t}). A mentési kulcs kell hozzá. Folytatod?": "Восстановление перезапишет данные на этом устройстве копией из аккаунта ({t}). Понадобится ключ копии. Продолжить?",
  "Visszatöltve a fiókból. A nézetek frissülnek.": "Восстановлено из аккаунта. Экраны обновляются.",
  "Töröljük a fiókodból a tárolt mentéseidet is?": "Удалить также копии, хранящиеся в вашем аккаунте?",
  "A fiókodban tárolt mentés törölve.": "Копия в аккаунте удалена.",
});

// Igetanulmányozó: two translations side by side, Biblia prémium (owner TG 34609, 2026-11-03)
Object.assign(window.PP_FORD_SZOTAR.ru, {
  "Igetanulmányozó": "Изучение стихов",
  "Igetanulmányozó ingyen naponta {db} fejezet, ma még {n}.": "Изучение стихов бесплатно {db} главы в день, сегодня осталось {n}.",
  "Ma már {db} fejezetet összevetettél az igetanulmányozóban. Holnap újra jár; Biblia prémiummal korlátlanul összevetheted a fordításokat.": "Сегодня вы уже сравнили {db} главы в изучении стихов. Завтра они снова будут; с Библией Премиум вы сравниваете переводы без ограничений.",
  "A két fordítás felcserélése": "Поменять переводы местами",
  "Előző fejezet": "Предыдущая глава",
  "Következő fejezet": "Следующая глава",
  "Ezt a fordítást most nem sikerült betölteni. Letöltés után internet nélkül is működik.": "Этот перевод сейчас не удалось загрузить. После загрузки он работает и без интернета.",
  "Válassz egy második fordítást az összevetéshez.": "Выберите второй перевод для сравнения.",
  "A két fordítás más nyelvű: a szavak eltérését csak azonos nyelvű fordításoknál jelöljük.": "Переводы на разных языках: различающиеся слова отмечаются только между переводами на одном языке.",
  "A kiemelt szavak eltérnek a másik fordítástól.": "Выделенные слова отличаются от другого перевода.",
  "A második fordításban ez a könyv nincs meg.": "Этой книги нет во втором переводе.",
  "nincs megfelelő vers": "нет соответствующего стиха",
  "Első fordítás": "Первый перевод",
  "Második fordítás": "Второй перевод",
  "Könyv": "Книга",
  "Két fordítás összevetése": "Сравнить два перевода",
  "Maradsz ennél a lépésnél · koppints a folytatáshoz": "Вы остаётесь на этом шаге · коснитесь, чтобы продолжить",
  "Palackos víz (autó)": "Бутилированная вода (машина)",
  "Energiaszelet (autó)": "Энергетические батончики (машина)",
  "Powerbank (autó)": "Пауэрбанк (машина)",
  "Powerbank (hétvégi ház)": "Пауэрбанк (дача)",
  "Powerbank (rejtek)": "Пауэрбанк (тайник)",
  "Gázpalack (rejtek)": "Газовый баллон (тайник)",
  // Ujdonsagok v43.465 (2026-11-08)
  "Biblia: a Beállításokban választható az olvasási háttér: Csillagos ég, Statikus zöld, vagy 3D galaxis, amely a telefon döntésére mozog (szédülékenyeknek nem ajánlott; felolvasás közben áll).": "Библия: в Настройках можно выбрать фон для чтения: Звёздное небо, Статичный зелёный или 3D-галактика, которая движется при наклоне телефона (не рекомендуется тем, у кого легко кружится голова; во время чтения вслух она неподвижна).",
  "Biblia: a könyvek között az apokrif könyvek polca alapból össze van csukva, egy koppintással kinyílik.": "Библия: в списке книг полка апокрифов по умолчанию свёрнута; одно касание открывает её.",
  "Biblia, lengyel UBG fordítás: a Prédikátor könyve és a Jelenések könyve rövidítése Kaz és Obj.": "Библия, польский перевод UBG: Екклесиаст и Откровение теперь сокращаются как Kaz и Obj.",
  "Igekvíz és Igehely-párosító: felnőtt módban csak megjegyzésre érdemes igék jönnek (Zsoltárok, Példabeszédek, Jézus szavai, próféciák).": "Викторина по стихам и Сопоставление ссылок: во взрослом режиме попадаются только стихи, которые стоит запомнить (Псалмы, Притчи, слова Иисуса, пророчества).",
  "Vezetett ima: a felolvasott szöveg látható marad, és minden lépés megvárja, amíg a felolvasás véget ér.": "Ведомая молитва: читаемый текст остаётся видимым, и каждый шаг ждёт, пока чтение закончится.",
  "Igetanuló: a nyomtatott vágási útmutató szerint minden csíkot a két vágójel között félúton kell elvágni.": "Заучивание стихов: печатная инструкция по резке теперь говорит резать каждую полоску посередине между двумя метками.",
  "Gerah: tárca nélkül az app nem ígér letétet; a panel megmondja, hogy nincs tárca, és egy koppintással a tárcához visz. Az olvasási napok állapota a tárcával együtt átkerül a másik appba.": "Gerah: без кошелька приложение больше не обещает депозит; панель сообщает, что кошелька нет, и одно касание ведёт к кошельку. Состояние дней чтения переносится в другое приложение вместе с кошельком.",
  "Tablet: álló és fekvő elrendezés, a tablet elforgatható; a Biblia szövege kitölti a képernyőt, fekvő helyzetben a hivatkozások és jegyzetek oldalt nyílnak, és a kezdőlapon a világhelyzet csempéje jelenik meg.": "Планшет: вертикальная и горизонтальная раскладка, планшет можно поворачивать; текст Библии заполняет экран, в горизонтальном положении ссылки и заметки открываются сбоку, а на стартовой странице появляется плитка о положении в мире.",
  "Világhelyzet térkép: új Támadás réteg, a terrortámadások és tömeges gyilkosságok is megjelennek a térképen és a vezetett ima világhelyzet-lépésében.": "Карта ситуации в мире: новый слой Теракт; теракты и массовые убийства теперь видны на карте и в шаге о мире в молитве с руководством.",
  "Megvallások: a Szellemi fegyverek felvétele megvallás mindenkinek beépítve, a fegyverzet minden darabjához saját képpel.": "Исповедания: исповедание «Облечение в духовное всеоружие» встроено для всех, с отдельной картинкой для каждой части доспехов.",
  // t='attack' (TG 36837)
  "Terrortámadás / tömeges gyilkosság": "Теракт / массовое убийство",
  "Támadás": "Теракт",
  "Hírek alapján (48 óra):": "По новостям (48 часов):",
  "Közel van az Úr a megtört szívekhez. Állj most oda imádságban a gyászolók, a sebesültek és a mentők mellé.": "Близок Господь к сокрушённым сердцем. Встань сейчас в молитве рядом со скорбящими, ранеными и спасателями.",
  "Uram, vigasztald {hely} gyászolóit, gyógyítsd a sebesülteket, és ne engedd, hogy a gyűlölet mondja ki az utolsó szót.": "Господи, утешь скорбящих в регионе {hely}, исцели раненых и не дай ненависти сказать последнее слово.",
  // Névtelen statisztika (owner TG 36883, 2026-11-08, olvasas-stat.mjs)
  "Névtelen statisztika": "Анонимная статистика",
  "Ha bekapcsolod, egy nap végén az app egyetlen névtelen számsort küld: kerekítve hány percet olvastál és imádkoztál aznap, és melyik alkalmazásban. Nincs benne fiók, e-mail-cím és készülék-azonosító, az IP-címet sem tároljuk.": "Если ты включишь это, в конце дня приложение отправит один анонимный набор чисел: сколько минут (с округлением) ты читал Библию и молился в этот день и в каком приложении. В нём нет аккаунта, адреса электронной почты и идентификатора устройства, IP-адрес мы тоже не храним.",
  "Ebből csak napi összesítés készül (hányan olvastak és imádkoztak, átlagosan hány percet), amelyet a Wordlight oldalán közzéteszünk, de tíz főnél kisebb csoportot soha. A beküldött számsor nem köthető hozzád, ezért utólag nem törölhető; kikapcsolás után az app nem küld többet.": "Из этого составляются только ежедневные итоги (сколько человек читали и молились, в среднем сколько минут), которые мы публикуем на сайте Wordlight, но никогда для группы меньше десяти человек. Отправленные числа нельзя связать с тобой, поэтому их нельзя удалить позже; после отключения приложение больше ничего не отправляет.",
});
